const r = $json.result || {};
if (r.status !== 'success') throw new Error('Pilot list.php no respondio success: ' + JSON.stringify($json).slice(0, 300));
// ponytail: page_count de Pilot viene siempre 50; se calcula con rows_count
const n = Math.min(Math.ceil((Number((r.aditional_data || {}).rows_count) || 0) / 100), 50) || 1;
const out = [];
for (let p = 1; p <= n; p++) out.push({ json: { page: p } });
return out;

const H = 3600 * 1000, now = Date.now();
const pilot = {};
for (const it of $('Listar leads Pilot').all()) {
  const r = it.json.result || {};
  if (r.status !== 'success') throw new Error('Pilot list.php fallo: ' + JSON.stringify(it.json).slice(0, 300));
  // ford_digital_colombia = web; digital_ford = chatbot. Los dos los carga nuestro flujo.
  for (const x of (r.entitydata || [])) if (['ford_digital_colombia', 'digital_ford'].includes((x.origin || {}).code)) pilot[String(x.id).toUpperCase()] = x;
}
const rows = $('Leer base').all().map(i => i.json).filter(r => r.id);
const byGuid = {};
for (const r of rows) if (r.pilot_tracking_id) byGuid[String(r.pilot_tracking_id).toUpperCase()] = r;
const t = d => Date.parse(String(d || '').replace('+0000', 'Z'));
const tel = x => (x.prospect || {}).cellphone || '';
const noLlegaron = Object.values(pilot)
  .filter(x => now - t((x.created || {}).dt) > 2 * H && !byGuid[String(x.id).toUpperCase()])
  .map(x => ({ guid: x.id, tel: tel(x), nombre: (x.prospect || {}).firstname, creado: (x.created || {}).dt, asignado: ((x.asigned || {}).user || {}).fullname }));
const desincronizados = [];
for (const r of rows) {
  const x = pilot[String(r.pilot_tracking_id || '').toUpperCase()];
  if (!x) continue;
  if (r.lead === 'good_lead' && r.grado_interes && !(x.interest_level || {}).code) desincronizados.push({ id: r.id, tel: r.pilot_cellphone, base: 'good_lead ' + (r.grado_interes || ''), pilot: (x.status || {}).name + ', sin grado' });
  if (r.lead === 'bad_lead' && (x.status || {}).code === '100') desincronizados.push({ id: r.id, tel: r.pilot_cellphone, base: 'bad_lead', pilot: 'Sin Gestion' });
}
const noConfirmo = rows.filter(r => String(r.reason || '').startsWith('Pilot no confirm')).map(r => ({ id: r.id, tel: r.pilot_cellphone, reason: r.reason }));
const trabados = rows.filter(r => !r.lead && now - t(r.created_utc) > 26 * H && now - t(r.created_utc) < 48 * H).map(r => ({ id: r.id, tel: r.pilot_cellphone, status: r.status, creado: r.created_utc }));
const total = noLlegaron.length + desincronizados.length + noConfirmo.length + trabados.length;
return [{ json: { total, pilot_leads: Object.keys(pilot).length, base_leads: rows.length, noLlegaron, desincronizados, noConfirmo, trabados } }];

const j = $json;
if (!j.total) return []; // ponytail: sin diferencias no se manda nada
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const tabla = (titulo, nota, lista) => !lista.length ? '' :
  `<h3>${titulo} (${lista.length})</h3><p>${nota}</p><table border="1" cellpadding="4" style="border-collapse:collapse;font-size:13px"><tr>${Object.keys(lista[0]).map(k => `<th>${esc(k)}</th>`).join('')}</tr>` +
  lista.map(r => `<tr>${Object.values(r).map(v => `<td>${esc(v)}</td>`).join('')}</tr>`).join('') + '</table>';
const html = `<p>Últimas 48 h: ${j.pilot_leads} leads en Pilot (ford_digital_colombia), ${j.base_leads} en la base.</p>` +
  tabla('No llegaron a la base', 'Están en Pilot y no tenemos registro. Probable caída del webhook o del n8n.', j.noLlegaron) +
  tabla('Desincronizados', 'La base y Pilot dicen cosas distintas.', j.desincronizados) +
  tabla('Pilot no confirmó', 'Pilot no aceptó la calificación al cerrar.', j.noConfirmo) +
  tabla('Trabados', 'Más de 26 h sin cerrar.', j.trabados);
return [{ json: { subject: `Ford Colombia: ${j.total} diferencias Pilot vs base`, html } }];

